import { Controller, Param, Post, UseGuards } from '@nestjs/common';
import { TenantGuard, type AuthContext } from '../../auth/tenant.guard';
import { CurrentUser } from '../../auth/current-user.decorator';
import { SigningService } from './signing.service';

/**
 * POST /invoices/:id/sign
 *
 * The body is empty. The signing service rebuilds the UBL from the DB row
 * (SEC-001) and signs the server-generated bytes — a client-supplied XML is
 * never accepted.
 */
@Controller('invoices/:id/sign')
@UseGuards(TenantGuard)
export class SigningController {
  constructor(private readonly signing: SigningService) {}

  @Post()
  sign(@CurrentUser() u: AuthContext, @Param('id') id: string) {
    return this.signing.sign(u.tenantId, id, u.userId);
  }
}
